/**
 * Deterministic 3D packer.
 *
 * Strategy: "maximal-space" extreme-point placement.
 *  - Items are considered in a caller-supplied deterministic order.
 *  - For each item we scan a set of candidate anchor points (initially the box
 *    origin, then the corner points generated by each placement).
 *  - At each anchor we try every allowed rotation and keep the candidate that
 *    maximises contact area with the already-placed items, tie-broken by
 *    lowest x, then y, then z so the result is fully reproducible.
 *
 * There is no randomness anywhere: same input => same output, always.
 */

import {
  EPS,
  contactArea,
  fits,
  orientations,
  rotations,
  volume,
  type Point3,
  type Size3,
} from './geometry';
import type { ItemInstance, Placement, Rotation, BoxType } from './types';

export interface PackOptions {
  allowRotation: boolean;
  maxWeight: number;
  maxItems?: number;
  /** Upper bound on retained anchor points. Higher = denser pack, slower. */
  maxAnchors?: number;
}

export interface PackResult {
  placements: Placement[];
  /** Items that did not fit into this box. */
  leftovers: ItemInstance[];
  weight: number;
  usedVolume: number;
}

function key(p: Point3, r: Rotation): string {
  return `${rounded(p.x)},${rounded(p.y)},${rounded(p.z)}#${r}`;
}

function rounded(v: number): number {
  // Quantise anchors so duplicate corners collapse reliably.
  return Math.round(v * 1e4) / 1e4;
}

/**
 * Pack as many of `items` (in the given order) as possible into one box.
 */
const rotCache = new Map<string, { rotation: Rotation; size: Size3 }[]>();

/** Rotations for a dimension triple, memoised across all packing calls. */
function rotationsCached(l: number, w: number, h: number): { rotation: Rotation; size: Size3 }[] {
  const k = `${l}|${w}|${h}`;
  let v = rotCache.get(k);
  if (!v) {
    v = rotations(l, w, h);
    rotCache.set(k, v);
  }
  return v;
}

export function packBox(
  box: BoxType,
  items: ItemInstance[],
  options: PackOptions,
): PackResult {
  const placements: Placement[] = [];
  const placedUids = new Set<string>();
  const anchorKeys = new Set<string>(['0,0,0#0']);
  let anchors: Point3[] = [{ x: 0, y: 0, z: 0 }];

  let weight = 0;
  let usedVolume = 0;
  const maxItems = options.maxItems ?? Number.POSITIVE_INFINITY;
  const maxWeight = options.maxWeight;
  const maxAnchors = options.maxAnchors ?? 48;

  // Items are processed in the caller-supplied deterministic order using a
  // forward cursor rather than rescanning the whole list after each placement.
  // Rescanning made packing quadratic; with many items that dominated runtime.
  // Pass 1 places each item at its first viable opportunity; pass 2 revisits
  // the leftovers, because a big item can leave pockets that small items fit.
  const leftovers: ItemInstance[] = [];

  const tryPlace = (item: ItemInstance): boolean => {
    if (placements.length >= maxItems) return false;
    if (weight + item.weight > maxWeight + EPS) return false;

    const rots = options.allowRotation
      ? rotationsCached(item.length, item.width, item.height)
      : [{ rotation: 'XY' as Rotation, size: { dx: item.length, dy: item.width, dz: item.height } }];

    let best: {
      anchor: Point3;
      size: Size3;
      rotation: Rotation;
      score: number;
    } | null = null;

    for (const anchor of anchors) {
      for (const { rotation, size } of rots) {
        if (!fits(anchor, size, box.length, box.width, box.height)) continue;
        if (collidesFast(anchor, size, placements)) continue;
        const score = contactArea(anchor, size, placements);
        if (
          best === null ||
          score > best.score + EPS ||
          (Math.abs(score - best.score) <= EPS && better(anchor, rotation, best.anchor, best.rotation))
        ) {
          best = { anchor, size, rotation, score };
        }
      }
    }

    if (!best) return false;

    const placement: Placement = {
      uid: item.uid,
      productId: item.productId,
      sku: item.sku,
      name: item.name,
      x: round3(best.anchor.x),
      y: round3(best.anchor.y),
      z: round3(best.anchor.z),
      dx: best.size.dx,
      dy: best.size.dy,
      dz: best.size.dz,
      weight: item.weight,
      rotation: best.rotation,
    };
    placements.push(placement);
    placedUids.add(item.uid);
    weight += item.weight;
    usedVolume += volume(best.size);

    anchors = addAnchors(anchors, anchorKeys, placements, placement, maxAnchors);
    return true;
  };

  // Pass 1: sequential placement.
  const skipped: ItemInstance[] = [];
  for (const item of items) {
    if (placements.length >= maxItems) break;
    if (!tryPlace(item)) skipped.push(item);
  }

  // Pass 2: retry items that did not fit on the first sweep. Repeat until a
  // full pass places nothing, so newly freed pockets get filled too.
  let changed = true;
  while (changed && placements.length < maxItems) {
    changed = false;
    const stillSkipped: ItemInstance[] = [];
    for (const item of skipped) {
      if (placements.length >= maxItems) {
        stillSkipped.push(item);
        continue;
      }
      if (tryPlace(item)) {
        changed = true;
      } else {
        stillSkipped.push(item);
      }
    }
    skipped.length = 0;
    skipped.push(...stillSkipped);
  }
  leftovers.push(...skipped);

  return { placements, leftovers, weight, usedVolume };
}

function better(a: Point3, ra: Rotation, b: Point3, rb: Rotation): boolean {
  if (Math.abs(a.x - b.x) > EPS) return a.x < b.x;
  if (Math.abs(a.y - b.y) > EPS) return a.y < b.y;
  if (Math.abs(a.z - b.z) > EPS) return a.z < b.z;
  return ra < rb;
}

function round3(v: number): number {
  return Math.round(v * 1e4) / 1e4;
}

function collidesFast(p: Point3, size: Size3, placed: Placement[]): boolean {
  for (let i = 0; i < placed.length; i++) {
    const it = placed[i];
    if (
      p.x < it.x + it.dx - EPS &&
      it.x < p.x + size.dx - EPS &&
      p.y < it.y + it.dy - EPS &&
      it.y < p.y + size.dy - EPS &&
      p.z < it.z + it.dz - EPS &&
      it.z < p.z + size.dz - EPS
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Maintain the anchor (extreme point) set after a placement.
 *
 * Without pruning the anchor list grows by three points per item, which makes
 * packing O(n^2) and far too slow for realistic catalogues. We therefore:
 *   - drop anchors buried inside a placed box (they can never be used),
 *   - cap the remaining set, keeping the anchors with the most surrounding
 *     contact surface, which are the ones that produce tight packings.
 *
 * Note: coordinate-wise "dominance" pruning is deliberately NOT used. An anchor
 * closer to the origin always dominates an anchor further out along the same
 * axis, so it would delete every usable anchor except one.
 *
 * All steps are deterministic.
 */
function addAnchors(
  anchors: Point3[],
  keys: Set<string>,
  placed: Placement[],
  p: Placement,
  maxAnchors: number,
): Point3[] {
  const x = p.x + p.dx;
  const y = p.y + p.dy;
  const z = p.z + p.dz;
  const candidates: Point3[] = [
    { x, y: p.y, z: p.z },
    { x: p.x, y, z: p.z },
    { x: p.x, y: p.y, z },
  ];

  const all = anchors.slice();
  for (const c of candidates) {
    const k = key(c, 'XY');
    if (keys.has(k)) continue;
    keys.add(k);
    all.push(c);
  }

  // 1. Remove anchors buried inside any placed box.
  const free = all.filter((a) => !buried(a, placed));
  if (free.length <= maxAnchors) return free;

  // 2. Keep the most promising anchors: those touching the most existing
  //    surface area are where the next item will nestle best.
  const scored = free.map((a) => ({ a, score: anchorContact(a, placed) }));
  scored.sort(
    (p, q) => q.score - p.score || p.a.z - q.a.z || p.a.y - q.a.y || p.a.x - q.a.x,
  );
  return scored.slice(0, maxAnchors).map((s) => s.a);
}

/** How much already-placed surface meets this anchor point. */
function anchorContact(a: Point3, placed: Placement[]): number {
  let score = 0;
  for (const it of placed) {
    if (Math.abs(it.x + it.dx - a.x) < EPS) score += it.dy * it.dz;
    if (Math.abs(it.y + it.dy - a.y) < EPS) score += it.dx * it.dz;
    if (Math.abs(it.z + it.dz - a.z) < EPS) score += it.dx * it.dy;
  }
  return score;
}

function buried(a: Point3, placed: Placement[]): boolean {
  for (const it of placed) {
    if (
      a.x > it.x + EPS && a.x < it.x + it.dx - EPS &&
      a.y > it.y + EPS && a.y < it.y + it.dy - EPS &&
      a.z > it.z + EPS && a.z < it.z + it.dz - EPS
    ) {
      return true;
    }
  }
  return false;
}

/**
 * Count how many of the items can physically fit in a box, ignoring the
 * packing heuristic. Used to reject boxes that are obviously too small.
 */
export function boxCanFit(box: BoxType, item: ItemInstance, allowRotation: boolean): boolean {
  const rots = allowRotation
    ? orientations(item.length, item.width, item.height)
    : [{ dx: item.length, dy: item.width, dz: item.height }];
  return rots.some((s) =>
    fits({ x: 0, y: 0, z: 0 }, s, box.length, box.width, box.height),
  );
}